-- Fixed date-math caller profiles;selected target scope recorded separately.
DECLARE @ExpectedApiCount int=4;
INSERT @Apis VALUES
(1,N'toolbelt_datetime',N'TVF_DateBucketDate','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_DateBucketDate(''month'',3,''20260730'',''20260101'');',N'DECLARE @Rows table(Value date NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDate(''month'',3,''20260730'',''20260101''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(date,''20260701'',112) AND IsValid=1 AND ValidationCode=0) THROW 52097,N''DateMath fixed bucket oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDate(''month'',3,NULL,''20260101''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''DateMath NULL bucket oracle.'',13; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDate(''month'',0,''20260730'',''20260101''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=11) THROW 52097,N''DateMath width oracle.'',14;'),
(2,N'toolbelt_datetime',N'TVF_DateBucketDateTime2','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_DateBucketDateTime2(''hour'',2,''2026-07-30T13:34:56.1234567'',''2026-07-30T00:00:00'');',N'DECLARE @Rows table(Value datetime2(7) NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDateTime2(''hour'',2,''2026-07-30T13:34:56.1234567'',''2026-07-30T00:00:00''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(datetime2(7),''2026-07-30T12:00:00'') AND IsValid=1 AND ValidationCode=0) THROW 52097,N''DateMath fixed bucket oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDateTime2(''hour'',2,NULL,''2026-07-30T00:00:00''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''DateMath NULL bucket oracle.'',13; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDateTime2(''hour'',0,''2026-07-30T13:34:56.1234567'',''2026-07-30T00:00:00''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=11) THROW 52097,N''DateMath width oracle.'',14;'),
(3,N'toolbelt_datetime',N'TVF_DateBucketDateTimeOffset','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_DateBucketDateTimeOffset(''hour'',2,''2026-07-30T13:34:56.1234567+05:30'',''2026-07-30T00:00:00+05:30'');',N'DECLARE @Rows table(Value datetimeoffset(7) NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDateTimeOffset(''hour'',2,''2026-07-30T13:34:56.1234567+05:30'',''2026-07-30T00:00:00+05:30''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(datetimeoffset(7),''2026-07-30T12:00:00+05:30'') AND IsValid=1 AND ValidationCode=0 AND DATEPART(TZOFFSET,Value)=330) THROW 52097,N''DateMath fixed bucket oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDateTimeOffset(''hour'',2,NULL,''2026-07-30T00:00:00+05:30''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''DateMath NULL bucket oracle.'',13; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_datetime.TVF_DateBucketDateTimeOffset(''hour'',0,''2026-07-30T13:34:56.1234567+05:30'',''2026-07-30T00:00:00+05:30''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=11) THROW 52097,N''DateMath width oracle.'',14;'),
(4,N'toolbelt_datetime',N'TVF_CalendarDifference','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_CalendarDifference(''20200115'',''20220220'');',N'DECLARE @Rows table(Sign smallint NULL,Years int NULL,Months int NULL,Days int NULL); INSERT @Rows SELECT Sign,Years,Months,Days FROM toolbelt_datetime.TVF_CalendarDifference(''20200115'',''20220220''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Sign=1 AND Years=2 AND Months=1 AND Days=5) THROW 52097,N''DateMath calendar fixed oracle.'',15; DELETE @Rows; INSERT @Rows SELECT Sign,Years,Months,Days FROM toolbelt_datetime.TVF_CalendarDifference(''20220220'',''20200115''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Sign=-1 AND Years=2 AND Months=1 AND Days=5) THROW 52097,N''DateMath reversed calendar oracle.'',16; DELETE @Rows; INSERT @Rows SELECT Sign,Years,Months,Days FROM toolbelt_datetime.TVF_CalendarDifference(NULL,''20220220''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Sign IS NULL AND Years IS NULL AND Months IS NULL AND Days IS NULL) THROW 52097,N''DateMath NULL calendar oracle.'',17; DELETE @Rows; INSERT @Rows SELECT Sign,Years,Months,Days FROM toolbelt_datetime.TVF_CalendarDifference(''20200229'',''20210228''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Sign=1 AND Years=1 AND Months=0 AND Days=0) THROW 52097,N''DateMath clamped anniversary oracle.'',18;');
INSERT @Denied VALUES
(1,N'toolbelt_datetime',N'TVF_DateBucketCore','SELECT',N'SELECT * FROM toolbelt_datetime.TVF_DateBucketCore(''day'',1,''2026-01-02T00:00:00+00:00'',''2026-01-01T00:00:00+00:00'');'),
(2,N'toolbelt_core',N'USP_PrepareResultTable','EXECUTE',N'EXEC toolbelt_core.USP_PrepareResultTable @Hilfe=1;');
